describe('Browser Push Notifications for Urgent Alerts', () => {
  beforeEach(() => {
    cy.visit('/');
    cy.clearLocalStorage();
    cy.clearCookies();
  });

  it('should display browser push notification when urgent alert is triggered', () => {
    // Mock the Notification API
    cy.window().then((win) => {
      cy.stub(win, 'Notification').callsFake(function(title, options) {
        this.title = title;
        this.options = options;
        this.close = cy.stub();
      });
    });

    // Navigate to alerts page
    cy.visit('/alerts');

    // Request notification permission if not already granted
    cy.window().then((win) => {
      if (Notification.permission !== 'granted') {
        cy.stub(Notification, 'requestPermission').resolves('granted');
      }
    });

    // Trigger an urgent alert
    cy.get('[data-testid="create-urgent-alert-btn"]').click();
    cy.get('[data-testid="alert-title-input"]').type('Critical System Error');
    cy.get('[data-testid="alert-message-input"]').type('Database connection failed');
    cy.get('[data-testid="alert-priority-select"]').select('urgent');
    cy.get('[data-testid="submit-alert-btn"]').click();

    // Verify notification was triggered
    cy.window().then((win) => {
      expect(win.Notification).to.have.been.calledOnce;
      const notificationCall = win.Notification.getCall(0);
      expect(notificationCall.args[0]).to.equal('Critical System Error');
      expect(notificationCall.args[1].body).to.include('Database connection failed');
      expect(notificationCall.args[1].tag).to.equal('urgent-alert');
      expect(notificationCall.args[1].requireInteraction).to.be.true;
    });

    // Verify alert appears in UI
    cy.get('[data-testid="alert-item"]').should('be.visible');
    cy.get('[data-testid="alert-item"]').should('contain', 'Critical System Error');
    cy.get('[data-testid="alert-badge-urgent"]').should('be.visible');
  });

  it('should not send push notification for non-urgent alerts', () => {
    cy.window().then((win) => {
      cy.stub(win, 'Notification').callsFake(function(title, options) {
        this.title = title;
        this.options = options;
      });
    });

    cy.visit('/alerts');

    // Create a non-urgent alert
    cy.get('[data-testid="create-alert-btn"]').click();
    cy.get('[data-testid="alert-title-input"]').type('Informational Update');
    cy.get('[data-testid="alert-message-input"]').type('System maintenance scheduled');
    cy.get('[data-testid="alert-priority-select"]').select('info');
    cy.get('[data-testid="submit-alert-btn"]').click();

    // Verify notification was NOT triggered
    cy.window().then((win) => {
      expect(win.Notification).to.not.have.been.called;
    });

    // Verify alert still appears in UI but without urgent styling
    cy.get('[data-testid="alert-item"]').should('be.visible');
    cy.get('[data-testid="alert-badge-urgent"]').should('not.exist');
  });

  it('should handle notification permission denial gracefully', () => {
    cy.window().then((win) => {
      cy.stub(Notification, 'requestPermission').resolves('denied');
    });

    cy.visit('/alerts');

    // Attempt to create urgent alert
    cy.get('[data-testid="create-urgent-alert-btn"]').click();
    cy.get('[data-testid="alert-title-input"]').type('Critical Alert');
    cy.get('[data-testid="alert-message-input"]').type('Urgent action required');
    cy.get('[data-testid="alert-priority-select"]').select('urgent');
    cy.get('[data-testid="submit-alert-btn"]').click();

    // Verify fallback UI notification appears
    cy.get('[data-testid="in-app-notification"]').should('be.visible');
    cy.get('[data-testid="in-app-notification"]').should('contain', 'Critical Alert');
    cy.get('[data-testid="notification-permission-prompt"]').should('be.visible');
  });

  it('should close push notification when user clicks close button', () => {
    let notificationInstance;

    cy.window().then((win) => {
      cy.stub(win, 'Notification').callsFake(function(title, options) {
        this.title = title;
        this.options = options;
        this.close = cy.stub();
        notificationInstance = this;
      });
    });

    cy.visit('/alerts');

    // Create urgent alert
    cy.get('[data-testid="create-urgent-alert-btn"]').click();
    cy.get('[data-testid="alert-title-input"]').type('Urgent Alert');
    cy.get('[data-testid="alert-message-input"]').type('Action needed');
    cy.get('[data-testid="alert-priority-select"]').select('urgent');
    cy.get('[data-testid="submit-alert-btn"]').click();

    // Simulate user closing notification
    cy.window().then((win) => {
      expect(win.Notification).to.have.been.called;
      notificationInstance.close();
      expect(notificationInstance.close).to.have.been.called;
    });
  });

  it('should batch multiple urgent alerts into single notification', () => {
    cy.window().then((win) => {
      cy.stub(win, 'Notification').callsFake(function(title, options) {
        this.title = title;
        this.options = options;
      });
    });

    cy.visit('/alerts');

    // Create first urgent alert
    cy.get('[data-testid="create-urgent-alert-btn"]').click();
    cy.get('[data-testid="alert-title-input"]').type('First Alert');
    cy.get('[data-testid="alert-message-input"]').type('First urgent issue');
    cy.get('[data-testid="alert-priority-select"]').select('urgent');
    cy.get('[data-testid="submit-alert-btn"]').click();

    // Create second urgent alert quickly
    cy.get('[data-testid="create-urgent-alert-btn"]').click();
    cy.get('[data-testid="alert-title-input"]').type('Second Alert');
    cy.get('[data-testid="alert-message-input"]').type('Second urgent issue');
    cy.get('[data-testid="alert-priority-select"]').select('urgent');
    cy.get('[data-testid="submit-alert-btn"]').click();

    // Verify only one batched notification was sent
    cy.window().then((win) => {
      expect(win.Notification.callCount).to.equal(1);
      const notificationCall = win.Notification.getCall(0);
      expect(notificationCall.args[1].body).to.include('2 urgent alerts');
    });
  });
});
